import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { RUNTIME_COMMAND_ENVELOPE_VERSION } from "@moe/contracts";
import { SqliteEventStore } from "@moe/store";
import { expect, it } from "vitest";

import { createStoreDependencies } from "./daemon-store-dependencies.js";
import { handleCommandRequest } from "./http/http-adapter.js";
import { WIRE_PROTOCOL_VERSION } from "./http/http-contract.js";

const CREDENTIAL = "approval-intent-probe-credential";
const PROJECT = "proj-approval-intent-probe";

function durableCounts(storePath: string): Readonly<{ decisions: number; events: number }> {
  const store = SqliteEventStore.openForProject(storePath, PROJECT);
  try {
    return Object.freeze({
      decisions: store.readCommandDecisionsAfter(0n, 1_000).items.length,
      events: store.readEventsAfter(0n, 1_000).items.length,
    });
  } finally {
    store.close();
  }
}

it("refuses the published but unwired approval intent command without durable writes", () => {
  const directory = mkdtempSync(join(tmpdir(), "moe-approval-intent-probe-"));
  const storePath = join(directory, "store.db");
  const provider = createStoreDependencies({
    clock: () => "2026-08-27T12:00:00.000Z",
    credential: CREDENTIAL,
    principalId: "operator-local",
    projectId: PROJECT,
    storePath,
  });
  try {
    const before = durableCounts(storePath);
    const response = handleCommandRequest(provider.provide(), {
      body: new TextEncoder().encode(JSON.stringify({
        commandId: "cmd-approval-intent-probe",
        commandKind: "approval.decide_intent",
        correlationId: "corr-approval-intent-probe",
        expectedVersion: 0,
        payload: {},
        requestDigest: "a".repeat(64),
        schemaVersion: RUNTIME_COMMAND_ENVELOPE_VERSION,
        sessionCredential: CREDENTIAL,
        targetAggregateId: "approval-intent-probe",
      })),
      credential: CREDENTIAL,
      protocolVersion: WIRE_PROTOCOL_VERSION,
    });

    expect(response).toMatchObject({
      error: { code: "INPUT_INVALID" },
      httpStatus: 400,
      ok: false,
      outcome: "REFUSED",
      stage: "REGISTRY",
    });
    expect(durableCounts(storePath)).toEqual(before);
  } finally {
    provider.close();
    rmSync(directory, { force: true, recursive: true });
  }
});
```
This drives createStoreDependencies(...).provide() and the real synchronous HTTP ingress, asserts exact code INPUT_INVALID at layer/stage REGISTRY, and verifies both durable event and decision counts are unchanged.
